 *  date and binds the claims that counted then to their figures then. Refused for a date after the sheet's
 *  today, or before the person was on the sheet. */
public class TakeStatement {
    public void take(@RequestParam(name = "asof", required = false) String asof, @Val Person person,
            PersonRepository people, ClaimRepository claims, RateRepository rates, SheetRepository sheets,
            SettingRepository settings, PoolRepository pools) throws InvalidPersonException {
        String sheetId = person.getSheetId();
        LocalDate today = sheets.today(sheetId);
        LocalDate on = today;
        Person then = person;
        List<Claim> own;
        List<Rate> sheetRates;
        DatedSetting floor;
        Dues.Late late;
        BigDecimal cap;
        if (asof == null || asof.isBlank()) {
            own = claims.listOf(sheetId, person.getId());
            sheetRates = rates.list(sheetId);
            floor = settings.floor(sheetId);
            late = settings.late(sheetId, today);
            cap = settings.cap(sheetId);
            if (cap != null) cap = Rollup.capLessCuts(cap, pools.cutTotals(sheetId).get(person.getId()));
        } else {
            try {
                on = LocalDate.parse(asof.trim());
            } catch (DateTimeParseException e) {
                throw new InvalidPersonException("The statement date must be a date");
            }
            if (on.isAfter(today)) {
                throw new InvalidPersonException("The statement date cannot be after the sheet's today");
            }
            if (people.addedAfter(sheetId, person.getId(), on)) {
                throw new InvalidPersonException("The person was not on the sheet on the statement date");
            }
            then = people.findAsOf(sheetId, person.getId(), on);
            own = claims.listOfAsOf(sheetId, person.getId(), on);
            sheetRates = rates.listAsOf(sheetId, on);
            floor = settings.datedAsOf(sheetId, SettingRepository.FLOOR, SettingRepository.DEFAULT_FLOOR, on);
            late = settings.lateAsOf(sheetId, on);
            cap = settings.capAsOf(sheetId, on);
            if (cap != null) cap = Rollup.capLessCuts(cap, pools.cutTotalsAsOf(sheetId, on).get(person.getId()));
            person.setStatedAsOf(on.toString());
        }
        // The figure each counting claim is bound to, by claim id.
        Map<Long, String> figures = new HashMap<>();
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        boolean kept = false;
        for (Claim c : own) {
            if (!then.countsLive(c)) continue;
            String grade = then.gradeOn(c.getDate());
            Rate rate = RateRepository.inForce(sheetRates, grade, c.getDate(), c.getId());
            String live = rate == null ? null : Dues.of(c.getAmount(), rate.pct(), late.rounding(c.getRoundDate()));
            String shown = Dues.shown(c, live, floor.on(c.getDate()), late);
            kept |= c.getSettledDue() != null || c.isBound()
                    || (rate != null && (!grade.equals(then.getGrade())
                            || !LocalDate.parse(c.getDate()).isAfter(on)));
            if (shown != null) total = total.add(new BigDecimal(shown));
            // The due as shown is bound, late charge included: it no longer follows the sheet's today.
            figures.put(c.getId(), shown);
        }
        for (Claim c : claims.listOf(sheetId, person.getId())) {
            if (figures.containsKey(c.getId())) c.bind(true, figures.get(c.getId()));
            else c.bind(false, null);
            claims.updateBinding(c);
        }
        boolean na = RateRepository.inForce(sheetRates, then.getGrade(), on.toString()) == null && !kept;
        if (cap != null && total.compareTo(cap) > 0) total = cap.setScale(2);
        String stated = na ? null : total.toPlainString();
        if (asof == null || asof.isBlank()) {
            // Taken now, it records the due-total their row shows: their parts of others' shared claims
            // count, and the parts others hold of theirs do not.
            Rollup.Figures now = Rollup.of(sheetId, people, claims, rates, sheets, settings, pools).people()
                    .get(person.getId());
            if (now != null) stated = now.dueTotal();
        }
        person.stated(stated, on.toString(), figures.size());
        people.updateStatements(person);
    }
}
    /** As {@link #settle}, the due frozen being {@code asOfDue}'s when given (else the due now). */
    static void settle(String by, Claim claim, boolean judged, PersonRepository people, RateRepository rates,
            PeriodRepository periods, RoleRepository roles, SettingRepository settings, SheetRepository sheets,
            Supplier<String> asOfDue) throws ClaimStatusException, PeriodClosedException {
        if (!Permissions.allows(claim.getSheetId(), by, Permissions.SETTLE, roles, settings)) {
            throw new ClaimStatusException("Your role may not settle a claim");
        }
        periods.requireOpen(claim.getSheetId(), claim.getDueBy());
        if (!ClaimStatus.OPEN.name().equals(claim.getStatus())) {
            throw new ClaimStatusException("A " + claim.getStatus() + " claim cannot be settled");
        }
        if (claim.isDeferred()) {
            throw new ClaimStatusException("A deferred claim cannot be settled until " + claim.getDeferredUntil());
        }
        ClaimStatus settled = ClaimStatus.OPEN.moveTo(ClaimStatus.SETTLED);
        if (judged) requireFourEyes(by, claim);
        Person person = people.find(claim.getSheetId(), claim.getPersonId());
        String due = asOfDue != null ? asOfDue.get() : dueOf(claim, person, rates, settings, sheets);
        if (judged) requireProof(claim, person, due, settings);
        if (due != null && Role.CLERK.equals(roles.roleOf(claim.getSheetId(), by == null ? "" : by))) {
            BigDecimal limit = settings.clerkLimit(claim.getSheetId(),
                    person == null ? null : person.gradeOn(sheets.today(claim.getSheetId()).toString()));
            if (limit != null && new BigDecimal(due).compareTo(limit) > 0) {
                claim.setStatus(ClaimStatus.OPEN.moveTo(ClaimStatus.PENDING).name());
                return;
            }
        }
        claim.setStatus(settled.name());
        claim.setSettledDue(due);
    }

    /** The four-eyes and proof rules of settling, judged on the claim (unchanged) alone. */
    static void judge(String by, Claim claim, PersonRepository people, RateRepository rates,
            SettingRepository settings, SheetRepository sheets) throws ClaimStatusException {
        requireFourEyes(by, claim);
        Person person = people.find(claim.getSheetId(), claim.getPersonId());
        requireProof(claim, person, dueOf(claim, person, rates, settings, sheets), settings);
    }

    /** Refuses the user who opened the claim or last edited it. */
    static void requireFourEyes(String by, Claim claim) throws ClaimStatusException {
        if (claim.getOpenedBy() != null && claim.getOpenedBy().equals(by == null ? "" : by)) {
            throw new ClaimStatusException("The user who opened a claim cannot settle it");
        }
        if (claim.getEditedBy() != null && claim.getEditedBy().equals(by == null ? "" : by)) {
            throw new ClaimStatusException("The user who last edited a claim cannot settle it");
        }
    }

